<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { Search, Users, Play, Info, ChevronLeft, ChevronRight, LoaderCircle } from 'lucide-vue-next'
import PageHeading from '../components/PageHeading.vue'
import StatePanel from '../components/StatePanel.vue'
import { toast } from '../components/ToastStack.vue'
import { api, allPages, query, type Section, type Enrollment, type Page } from '../lib/api'
import { useWorkspace } from '../stores/workspace'
import { useAsync } from '../lib/useAsync'
const workspace = useWorkspace(), { loading, error, run } = useAsync()
const route = useRoute()
const sections = ref<Section[]>([]), items = ref<Enrollment[]>([]), studentId = ref(''), sectionId = ref(''), total = ref(0), page = ref(0), promotionId = ref(''), promoting = ref(false), size = 20
const pages = computed(() => Math.max(1, Math.ceil(total.value / size)))
async function load(reset = false) { if (reset) page.value = 0; await run(async () => { const result = await api<Page<Enrollment>>('/admin/enrollments' + query({ termId: workspace.termId, studentId: studentId.value.trim(), sectionId: sectionId.value, page: page.value, size })); items.value = result.items; total.value = result.total; sections.value = await allPages<Section>('/admin/sections' + query({ termId: workspace.termId })) }) }
watch(() => workspace.termId, () => { sectionId.value = typeof route.query.sectionId === 'string' ? route.query.sectionId : ''; promotionId.value = ''; void load(true) }, { immediate: true })
watch(() => route.query.sectionId, value => { sectionId.value = typeof value === 'string' ? value : ''; void load(true) })
async function promote() { if (!promotionId.value) return; promoting.value = true; try { const result = await api<{ processed: number; promotionPending: boolean }>('/admin/promotions/run', { method: 'POST', body: { sectionId: promotionId.value } }); toast(`本次已检查${result.processed}名候补。${result.promotionPending ? '仍有待处理队列，后台将继续。' : '当前递补已处理完成。'}`); await load() } catch (e) { toast(e instanceof Error ? e.message : '递补未能完成', true) } finally { promoting.value = false } }
function paginate(delta: number) { page.value += delta; void load() }
</script>
<template><PageHeading eyebrow="FAIR CHOICES, CLEAR RECORDS" title="选课与递补" description="查看真实选课记录，关注每一个名额的有序流转。"><select v-model="workspace.termId" class="select-control" aria-label="选择学期"><option v-for="term in workspace.terms" :key="term.id" :value="term.id">{{ term.name }}</option></select></PageHeading><div class="content-columns"><section class="card"><div class="card-header"><div><h2>全学期选课记录</h2><p>共 {{ total }} 条 · 教务只读查看，学生自行选退课</p></div><Users :size="18" class="muted"/></div><form class="filter-bar" @submit.prevent="load(true)"><label class="search-field"><Search :size="14"/><input v-model="studentId" aria-label="按学号筛选" placeholder="输入完整学号筛选"></label><select v-model="sectionId" class="select-control" aria-label="按教学班筛选"><option value="">全部教学班</option><option v-for="section in sections" :key="section.id" :value="section.id">{{ section.courseTitle }} · {{ section.id }}</option></select><button class="button button-small" :disabled="loading">筛选记录</button></form><StatePanel v-if="loading" loading/><StatePanel v-else-if="error" :error="error" @retry="load()"/><StatePanel v-else-if="!items.length" title="没有符合条件的选课记录" description="可以调整学号、教学班或学期筛选。"/><div v-else class="table-wrap"><table><caption class="sr-only">教务选课记录</caption><thead><tr><th>学生 / 学号</th><th>课程 / 教学班</th><th>教师</th><th>学分</th><th>记录状态</th><th>成绩状态</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{ item.studentName }}</strong><small>{{ item.studentId }}</small></td><td><strong>{{ item.courseTitle }}</strong><small>{{ item.sectionId }}</small></td><td>{{ item.teacherName }}</td><td>{{ item.credits }}</td><td><span class="tag" :class="{ 'tag-neutral': item.state === 'WITHDRAWN' }">{{ item.state === 'WITHDRAWN' ? '已退课' : '已选中' }}</span></td><td>{{ item.grade == null ? '尚未发布' : Number(item.grade).toFixed(1) }}</td></tr></tbody></table></div><div v-if="total" class="card-footer"><span>第 {{ page + 1 }} / {{ pages }} 页</span><div class="pagination"><button aria-label="上一页" :disabled="page === 0 || loading" @click="paginate(-1)"><ChevronLeft :size="14"/></button><button aria-label="下一页" :disabled="page + 1 >= pages || loading" @click="paginate(1)"><ChevronRight :size="14"/></button></div></div></section><aside class="stack"><section class="aside-card"><div class="aside-icon"><Play :size="18"/></div><h3>让空余名额，<br>有序回到需要的人手中。</h3><p>后台会持续处理待递补队列。需要立即核查时，也可以对一个教学班执行同样的有界递补。</p><label class="field mt-20">选择教学班<select v-model="promotionId" :disabled="promoting"><option value="" disabled>请选择教学班</option><option v-for="section in sections" :key="section.id" :value="section.id">{{ section.courseTitle }} · {{ section.id }}（候补{{ section.waitingCount }}人）</option></select></label><button class="button mt-20" style="width:100%" :disabled="promoting || !promotionId" @click="promote"><LoaderCircle v-if="promoting" class="spin" :size="14"/><Play v-else :size="13"/>{{ promoting ? '正在处理递补…' : '立即检查递补' }}</button></section><div class="notice-banner"><Info :size="16"/><span>每轮最多核查20人，并在时间预算内提交进度。资格变化会记录原因并通知学生，直接选课不能越过有效候补队列。</span></div></aside></div></template>
